  "Intention · resonance · creation": "Absicht · Resonanz · Schöpfung",
  "Intention · what do you choose to create?": "Absicht · was möchtest du erschaffen?",
  "Interdim.": "Interdim.",
  "Interdim. ({n})": "Interdimensionale ({n})",
